package com.scamshield.admin; import com.scamshield.common.repo.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminController { final IncidentRepository incidents; final ReportRepository reports; final PhoneRiskRepository risks; public AdminController(IncidentRepository i,ReportRepository r,PhoneRiskRepository p){incidents=i;reports=r;risks=p;} private void auth(String key){String expected=System.getenv().getOrDefault("SCAMSHIELD_ADMIN_KEY","demo-admin-key");if(key==null||!key.equals(expected))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.UNAUTHORIZED,"Admin authentication required");} @GetMapping("/dashboard") public Map<String,Object> dashboard(@RequestHeader(value="X-Admin-Key",required=false) String key){auth(key);var high=risks.findByLevelIn(List.of("HIGH","CRITICAL"));return Map.of("activeIncidents",incidents.findAllByOrderByUpdatedAtDesc().stream().filter(x->!x.status.equals("RESOLVED")).count(),"reportsToday",reports.countByCreatedAtAfter(LocalDateTime.now().toLocalDate().atStartOfDay()),"highRiskNumbers",high.size(),"criticalNumbers",risks.findByLevelIn(List.of("CRITICAL")).size(),"providerImpersonationReports",reports.findAll().stream().filter(x->x.claimedProvider!=null&&!x.claimedProvider.equals("Other")).count(),"incidents",incidents.findAllByOrderByUpdatedAtDesc(),"highRisk",high,"recentReports",reports.findTop20ByOrderByCreatedAtDesc());} @GetMapping("/numbers/{phone}") public Map<String,Object> number(@PathVariable String phone,@RequestHeader(value="X-Admin-Key",required=false) String key){auth(key);String normalized=phone.replaceAll("[\\s-]","");if(normalized.matches("^7[0-9]{7}$"))normalized="+267"+normalized;final String p=normalized;var risk=risks.findById(p).orElseThrow();return Map.of("risk",risk,"reports",reports.findByPhoneNumberOrderByCreatedAtDesc(p),"incidents",incidents.findAllByOrderByUpdatedAtDesc().stream().filter(x->x.phoneNumber.equals(p)).toList());} }
